originalTestEdits.after:
motion.dragBy(0.4f)
// Windows port: dragBy at v0.4.6 adds the delta (1f + 0.4f) up to the 1.5f clamp; the upstream literal 1.14f
// assumed the 0.35 resistance of ControlCenterMotionSpec.dragProgress.
assertEquals(1.4f, motion.progress, absoluteTolerance = 0.0001f)

motion.dragBy(20f)
// Windows port: the v0.4.6 clamp is 1.5f; the upstream literal 1.25f is 1f + ControlCenterMotionSpec.MaxOverExpansion.
assertEquals(1.5f, motion.progress)

motion.dragBy(-0.25f)
// Windows port: 1.5f - 0.25f; the upstream literal 1f followed from the 1.25f cap.
assertEquals(1.25f, motion.progress)
